CREATE TABLE el_organization_logos(org_id TEXT PRIMARY KEY REFERENCES el_organizations(id),version TEXT NOT NULL,mime TEXT NOT NULL CHECK(mime IN ('image/png','image/jpeg')),byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 1 AND 32768),iv TEXT NOT NULL,ciphertext TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(org_id,updated_by) REFERENCES el_memberships(org_id,user_id));
CREATE TRIGGER el_organization_logo_identity BEFORE UPDATE ON el_organization_logos WHEN NEW.org_id<>OLD.org_id BEGIN SELECT RAISE(ABORT,'Organization logo identity is immutable'); END;
